'use client'

import { useState } from 'react'
import type { DragSource } from '@/components/builder/drag'
import { useProject } from '@/components/ProjectProvider'

interface Props {
  drag: DragSource
  /** itemId is generated by the caller so the reducer stays pure. */
  onAdd: (packetDefId: string) => void
  onDragStartItem: (itemId: string) => void
  onDragEnd: () => void
}

export function MainSlot({ drag, onAdd, onDragStartItem, onDragEnd }: Props) {
  const { state, dispatch } = useProject()
  const [over, setOver] = useState(false)
  const [overItem, setOverItem] = useState<string | null>(null)

  const acceptingFromList = drag?.kind === 'candidate'

  return (
    <div
      onDragOver={(e) => {
        if (acceptingFromList) {
          e.preventDefault()
          setOver(true)
        }
      }}
      onDragLeave={() => setOver(false)}
      onDrop={(e) => {
        e.preventDefault()
        if (drag?.kind === 'candidate') {
          onAdd(drag.id)
        }
        setOver(false)
        onDragEnd()
      }}
      className={`rounded-lg border border-dashed p-4 transition ${
        over ? 'border-brand bg-brand/[5%]' : 'border-current/20'
      }`}
    >
      <div className="mb-2 flex items-center justify-between">
        <span className="text-xs opacity-60">主選欄（發送序列）</span>
        <button
          onClick={() => dispatch({ type: 'clear-main' })}
          disabled={state.main.length === 0}
          className="rounded border border-current/20 px-2 py-1 text-xs transition
                     hover:bg-current/5 disabled:cursor-not-allowed disabled:opacity-40"
        >
          全部刪除
        </button>
      </div>

      {state.main.length === 0 ? (
        <p className="py-8 text-center text-sm opacity-50">把上方的封包拖進來組成發送序列</p>
      ) : (
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-current/10 text-left opacity-60">
              <th className="w-14 py-2 font-normal">順序</th>
              <th className="py-2 font-normal">封包名稱</th>
              <th className="w-24 py-2 font-normal">重複</th>
              <th className="w-28 py-2 text-right font-normal">展開筆數</th>
              <th className="w-12 py-2 font-normal" />
            </tr>
          </thead>
          <tbody>
            {state.main.map((item, index) => {
              const def = state.packetDefs.find((d) => d.id === item.packetDefId)
              return (
                <tr
                  key={item.itemId}
                  draggable
                  onDragStart={() => onDragStartItem(item.itemId)}
                  onDragOver={(e) => {
                    if (drag?.kind === 'main') {
                      e.preventDefault()
                      // stop the event bubbling to the outer container, or it would show a drop hint too
                      e.stopPropagation()
                      setOverItem(item.itemId)
                    }
                  }}
                  onDragLeave={() => setOverItem((cur) => (cur === item.itemId ? null : cur))}
                  onDrop={(e) => {
                    if (drag?.kind === 'main') {
                      e.preventDefault()
                      e.stopPropagation()
                      if (drag.id !== item.itemId) {
                        dispatch({ type: 'reorder-main', itemId: drag.id, toIndex: index })
                      }
                    }
                    setOverItem(null)
                    onDragEnd()
                  }}
                  onDragEnd={() => {
                    setOverItem(null)
                    onDragEnd()
                  }}
                  className={`cursor-grab border-b border-current/5 active:cursor-grabbing ${
                    overItem === item.itemId && drag?.kind === 'main' && drag.id !== item.itemId
                      ? 'border-t-2 border-t-brand'
                      : ''
                  } ${drag?.kind === 'main' && drag.id === item.itemId ? 'opacity-40' : ''}`}
                >
                  <td className="py-2 opacity-50">
                    <span className="mr-1 select-none opacity-50" aria-hidden>
                      ⠿
                    </span>
                    {index + 1}
                  </td>
                  <td className="py-2 font-medium">{def?.name ?? '（已刪除）'}</td>
                  <td className="py-2">
                    <input
                      type="number"
                      min={1}
                      value={item.repeat}
                      onChange={(e) =>
                        dispatch({
                          type: 'set-repeat',
                          itemId: item.itemId,
                          repeat: Number(e.target.value) || 1,
                        })
                      }
                      className="w-16 rounded border border-current/20 bg-transparent px-2 py-1"
                    />
                  </td>
                  <td className="py-2 text-right tabular-nums">
                    {(def?.count ?? 0) * item.repeat}
                  </td>
                  <td className="py-2 text-right">
                    <button
                      onClick={() => dispatch({ type: 'remove-from-main', itemId: item.itemId })}
                      className="rounded px-2 py-1 text-xs opacity-60 transition hover:bg-current/10 hover:opacity-100"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      )}
    </div>
  )
}
